package com.investinator.remediation;
import static com.investinator.domain.Json.*;
import com.investinator.domain.Json;
import com.investinator.domain.Contracts.*;
import com.investinator.persistence.*;
import com.investinator.workflows.WorkflowService;
import com.investinator.monitoring.MonitoringService;
import com.investinator.api.ApiFailure;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.core.env.Environment;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
@Service @ConditionalOnProperty(name="investinator.persistence.enabled",havingValue="true")
public class RemediationPolicy {
    private final Store db;private final WorkflowService workflows;private final MonitoringService monitoring;private final ReplayExecutor executor;private final Environment env;
    public RemediationPolicy(Store db,WorkflowService w,MonitoringService m,ReplayExecutor e,Environment env){this.db=db;workflows=w;monitoring=m;executor=e;this.env=env;
        var tokens=new HashSet<String>();for(String key:List.of("REMEDIATION_PLAN_TOKEN","REMEDIATION_APPROVE_TOKEN","REMEDIATION_EXECUTE_TOKEN","REMEDIATION_VERIFY_TOKEN")){String value=env.getProperty(key,"");if(!value.isBlank()&&!tokens.add(value))throw new IllegalArgumentException("Remediation capabilities must be distinct");}}
    private void boundary(){if(!env.getProperty("investinator.demo-mode",Boolean.class,true))throw new ApiFailure(403,"Enterprise writes are hard-denied without independently authenticated change control");}
    private <T>T audited(String tenant,String id,String operation,String actor,Supplier<T> call){boundary();try{if(env.getProperty("investinator.remediation.read-only",Boolean.class,false))throw new ApiFailure(403,"Remediation is read-only");return call.get();}catch(ApiFailure denied){db.write(tenant,()->{workflows.audit(tenant,"remediation_denied",null,actor,obj("plan_id",id,"operation",operation,"reason","Policy or scope validation rejected request","correlation_id",id==null?java.util.UUID.randomUUID().toString():id));return null;});throw denied;}}
    public record Proposal(String incident_id,String action,String environment,Map<String,Object> parameters,String parent_plan){}
    public Map<String,Object> propose(String tenant,Proposal request,boolean persist){return audited(tenant,null,"proposal","demo.recovery_planner",()->db.write(tenant,()->{
        if(!"ReplayLab".equals(request.environment()))throw new ApiFailure(403,"Real environments have no executor");var definition=ActionRegistry.definition(request.action());ActionRegistry.arguments(request.action(),request.parameters());workflows.incident(tenant,request.incident_id());
        var runs=db.select(Table.REPLAY_RUNS,tenant,"incident_id=? and scenario=?",request.incident_id(),"kafka_disk_pressure");String run;
        if(runs.isEmpty()){
            var bound=db.jdbc.queryForList("select lifecycle,source_mode,result::text from monitor_incidents where tenant_id=? and id=?",tenant,request.incident_id());if(bound.isEmpty()||!bound.getFirst().get("source_mode").equals("SIMULATED")||!bound.getFirst().get("lifecycle").equals("INVESTIGATING"))throw new ApiFailure(403,"Named ReplayLab run or explicitly triaged simulated disk incident required");
            var investigation=map(Json.decode(bound.getFirst().get("result").toString()));var candidates=rows(investigation.get("candidate_causes"));if(candidates.isEmpty()||!candidates.getFirst().get("signal").equals("DISK_EXHAUSTED"))throw new ApiFailure(403,"Only simulated disk-pressure replay binding is supported");boolean fresh=rows(investigation.get("observed_symptoms")).stream().anyMatch(o->o.get("signal").equals("DISK_EXHAUSTED")&&o.get("state").equals("ABNORMAL")&&Instant.parse(o.get("observed_at").toString()).isAfter(Instant.now().minusSeconds(120)));if(!fresh)throw new ApiFailure(409,"Fresh simulated disk evidence required");run=id();if(persist)db.insert(Table.REPLAY_RUNS,tenant,obj("id",run,"scenario","kafka_disk_pressure","incident_id",request.incident_id(),"status","awaiting_approval","payload",obj("mode","simulated","owned_governed_sandbox",true,"source_incident",request.incident_id())));
        }else run=runs.getFirst().get("id").toString();
        var resources=db.jdbc.queryForList("select * from replay_resources where tenant_id=? and run_id=?",tenant,run);double original=97.8;int version=0;
        if(resources.isEmpty()){if(!runs.isEmpty()&&!runs.getFirst().get("status").equals("awaiting_approval"))throw new ApiFailure(409,"ReplayLab run is not awaiting governed recovery");if(persist)db.jdbc.update("insert into replay_resources(tenant_id,run_id,disk_percent) values(?,?,?)",tenant,run,original);}
        else{var resource=resources.getFirst();version=((Number)resource.get("version")).intValue();original=((Number)resource.get("disk_percent")).doubleValue();if(!"SIMULATED".equals(resource.get("source_mode")))throw new ApiFailure(403,"Replay resource provenance mismatch");if(((java.sql.Timestamp)resource.get("observed_at")).toInstant().isBefore(Instant.now().minusSeconds(120)))throw new ApiFailure(409,"Fresh replay precondition sample required");}
        boolean rollback=request.action().equals(ActionRegistry.RESTORE.code());double post;
        if(rollback){if(request.parent_plan()==null)throw new ApiFailure(422,"Explicit parent plan required for rollback");var parent=required(tenant,request.parent_plan());var prior=payload(parent);if(!parent.get("incident_id").equals(request.incident_id())||!prior.get("run_id").equals(run)||!prior.get("action").equals(ActionRegistry.RECOVER.code())||!Set.of("EXECUTED","VERIFIED","REQUIRES_MANUAL_INTERVENTION").contains(parent.get("state")))throw new ApiFailure(403,"Rollback parent is not a known executed recovery");if(db.jdbc.queryForObject("select count(*) from remediation_effects where tenant_id=? and plan_id=?",Integer.class,tenant,request.parent_plan())!=1)throw new ApiFailure(409,"No confirmed effect to roll back");post=((Number)prior.get("pre_disk_percent")).doubleValue();}
        else{if(request.parent_plan()!=null||original<=95)throw new ApiFailure(409,"Disk-pressure recovery precondition not satisfied");post=((Number)request.parameters().get("disk_percent")).doubleValue();}
        var plan=obj("action",definition.code(),"definition",definition,"incident_id",request.incident_id(),"run_id",run,"target","ReplayLab/"+run+"/broker-02","environment","ReplayLab","parameters",request.parameters(),"expected_resource_version",version,"pre_disk_percent",original,"post_disk_percent",post,"parent_plan",request.parent_plan(),"source_mode","SIMULATED","preconditions",List.of("Owned ReplayLab run","SIMULATED resource","Fresh sample and exact version"),"postconditions",List.of(rollback?"Original isolated pressure restored":"Simulated disk below 80","Independent current sampler matches effect version"));String hash=monitoring.hash(plan),id=id();
        if(persist){db.jdbc.update("insert into remediation_plans(tenant_id,id,incident_id,payload,plan_hash,expires_at) values(?,?,?,?::jsonb,?,now()+interval '10 minutes')",tenant,id,request.incident_id(),encode(plan),hash);workflows.audit(tenant,"remediation_proposed",request.incident_id(),"demo.recovery_planner",obj("plan_id",id,"hash",hash,"action",definition.code(),"target",plan.get("target"),"correlation_id",id));advanceMonitor(tenant,request.incident_id(),"AWAITING_APPROVAL");}
        return obj("plan_id",persist?id:null,"plan_hash",hash,"plan",plan,"state","PROPOSED","dry_run",!persist,"policy_decision",new ActionRegistry.PolicyDecision(true,false,"Exact scoped approval and independent verification required","SIMULATION_APPROVER","SIMULATED"));
    }));}
    private Map<String,Object> required(String tenant,String id){var rows=db.jdbc.queryForList("select *,payload::text as body from remediation_plans where tenant_id=? and id=?",tenant,id);if(rows.isEmpty())throw new ApiFailure(404,"Plan not found");return rows.getFirst();}
    private Map<String,Object> payload(Map<String,Object> row){return map(Json.decode(row.get("body").toString()));}
    private void integrity(Map<String,Object> row,String expected){var plan=payload(row);if(!Objects.equals(expected,row.get("plan_hash"))||!Objects.equals(expected,monitoring.hash(plan)))throw new ApiFailure(409,"Approved plan content changed");var definition=ActionRegistry.definition(plan.get("action").toString());ActionRegistry.arguments(definition.code(),map(plan.get("parameters")));if(!"ReplayLab".equals(plan.get("environment"))||!"SIMULATED".equals(plan.get("source_mode"))||!monitoring.hash(plan.get("definition")).equals(monitoring.hash(definition)))throw new ApiFailure(403,"Action definition or provenance mismatch");}
    public Map<String,Object> get(String tenant,String id){boundary();var row=required(tenant,id);return obj("plan_id",id,"plan",payload(row),"plan_hash",row.get("plan_hash"),"state",row.get("state"),"expires_at",((java.sql.Timestamp)row.get("expires_at")).toInstant().toString(),"outcome",row.get("outcome"),"approved_by",row.get("approved_by"),"approval_expires_at",row.get("approval_expires_at")==null?null:((java.sql.Timestamp)row.get("approval_expires_at")).toInstant().toString(),"revoked",row.get("revoked"));}
    /** Redacted staging export; source is application-append-only, NOT externally tamper-proof. */
    public Object auditEnvelope(String tenant,String id,String cursor){
        boundary();required(tenant,id);Instant after=Instant.EPOCH;String afterId="";
        if(cursor!=null)try{if(cursor.length()>256)throw new IllegalArgumentException();String[] parts=new String(Base64.getUrlDecoder().decode(cursor),java.nio.charset.StandardCharsets.UTF_8).split("\\|",-1);if(parts.length!=2||!parts[1].matches("[a-f0-9-]{36}"))throw new IllegalArgumentException();after=Instant.parse(parts[0]);afterId=parts[1];}catch(Exception invalid){throw new ApiFailure(422,"Invalid bounded audit cursor");}
        final var since=after;final var sinceId=afterId;
        var records=db.read(()->{db.jdbc.execute("set local statement_timeout='1500ms'");return db.jdbc.queryForList("select id,event,actor,created_at from audit_events where tenant_id=? and payload->>'plan_id'=? and event like 'remediation_%' and (created_at,id)>(?,?) order by created_at,id limit 101",tenant,id,java.sql.Timestamp.from(since),sinceId);});
        var envelopes=new ArrayList<Map<String,Object>>();for(var row:records.stream().limit(100).toList()){
            String event=row.get("event").toString(),actor=row.get("actor").toString();if(!event.matches("remediation_[a-z_]{1,60}"))event="remediation_unknown";
            if(!Set.of("demo.recovery_planner","demo.recovery_approver","demo.recovery_executor","demo.recovery_verifier").contains(actor))actor="UNKNOWN";
            envelopes.add(obj("schema_version",1,"tenant_id",tenant,"plan_id",id,"event_id",row.get("id"),"event",event,"actor_capability",actor,"recorded_at",((java.sql.Timestamp)row.get("created_at")).toInstant().toString(),"source_mode","SIMULATED","authority","AUDIT_ONLY_NO_APPROVAL_AUTHORITY"));
        }
        String next=null;if(records.size()>100){var last=records.get(99);next=Base64.getUrlEncoder().withoutPadding().encodeToString((((java.sql.Timestamp)last.get("created_at")).toInstant()+"|"+last.get("id")).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
        return obj("items",envelopes,"next_cursor",next,"external_sink","NOT_CONFIGURED","storage_assurance","APPLICATION_APPEND_ONLY_DATABASE_ADMIN_MUTABLE","redaction","FIXED_METADATA_ONLY_NO_PAYLOAD_OR_RESPONSE_TEXT");
    }
    public Object list(String tenant,String incident){boundary();if(incident!=null)workflows.incident(tenant,incident);var records=incident==null?db.jdbc.queryForList("select id,incident_id,state,created_at from remediation_plans where tenant_id=? order by created_at desc limit 50",tenant):db.jdbc.queryForList("select id,incident_id,state,created_at from remediation_plans where tenant_id=? and incident_id=? order by created_at desc limit 50",tenant,incident);return obj("items",records);}
    public Object postmortem(String tenant,String id){boundary();required(tenant,id);var rows=db.jdbc.queryForList("select payload::text from remediation_postmortems where tenant_id=? and plan_id=?",String.class,tenant,id);if(rows.isEmpty())throw new ApiFailure(404,"No independently verified postmortem yet");return Json.decode(rows.getFirst());}
    public Map<String,Object> approve(String tenant,String id,String hash,String decision){return audited(tenant,id,"approve","demo.recovery_approver",()->db.write(tenant,()->{var row=required(tenant,id);integrity(row,hash);if(decision.equals("REVOKE")){if(!Set.of("AUTHORIZED","PROPOSED").contains(row.get("state")))throw new ApiFailure(409,"In-flight execution requires manual intervention");db.jdbc.update("update remediation_plans set revoked=true,state='FAILED',outcome='APPROVAL_REVOKED' where tenant_id=? and id=?",tenant,id);}else{if(!decision.equals("APPROVE")||!row.get("state").equals("PROPOSED")||((java.sql.Timestamp)row.get("expires_at")).toInstant().isBefore(Instant.now()))throw new ApiFailure(403,"Pending unexpired plan required");db.jdbc.update("update remediation_plans set state='AUTHORIZED',approved_hash=?,approved_by='demo.recovery_approver',approval_expires_at=least(expires_at,now()+interval '120 seconds') where tenant_id=? and id=?",hash,tenant,id);db.jdbc.update("insert into remediation_outbox(tenant_id,plan_id) values(?,?)",tenant,id);}workflows.audit(tenant,"remediation_approval",row.get("incident_id").toString(),"demo.recovery_approver",obj("plan_id",id,"decision",decision,"approved_hash",hash,"correlation_id",id));return get(tenant,id);}));}
    public String claim(String tenant,String id,String hash,String key){return audited(tenant,id,"execute","demo.recovery_executor",()->db.write(tenant,()->{if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw new ApiFailure(422,"Execution idempotency key required");var row=required(tenant,id);integrity(row,hash);if(!row.get("state").equals("AUTHORIZED")||!Objects.equals(row.get("approved_hash"),hash)||Boolean.TRUE.equals(row.get("revoked"))||row.get("approval_expires_at")==null||!((java.sql.Timestamp)row.get("approval_expires_at")).toInstant().isAfter(Instant.now()))throw new ApiFailure(403,"Unexpired scoped approval required; repeated execution denied");if(db.jdbc.queryForObject("select count(*) from remediation_plans where tenant_id=? and execution_key=?",Integer.class,tenant,key)>0)throw new ApiFailure(409,"Execution key already consumed");var plan=payload(row);var resource=db.jdbc.queryForList("select version,disk_percent,observed_at from replay_resources where tenant_id=? and run_id=?",tenant,plan.get("run_id"));if(resource.isEmpty()||((Number)resource.getFirst().get("version")).intValue()!=((Number)plan.get("expected_resource_version")).intValue()||((java.sql.Timestamp)resource.getFirst().get("observed_at")).toInstant().isBefore(Instant.now().minusSeconds(120))||Double.compare(((Number)resource.getFirst().get("disk_percent")).doubleValue(),((Number)plan.get("pre_disk_percent")).doubleValue())!=0)throw new ApiFailure(409,"Resource preconditions changed or stale");String lease=id();db.jdbc.update("update remediation_plans set state='EXECUTING',execution_key=?,lease=?,lease_expires_at=now()+interval '10 seconds' where tenant_id=? and id=?",key,lease,tenant,id);db.jdbc.update("update remediation_outbox set state='CLAIMED',attempts=attempts+1,lease=? where tenant_id=? and plan_id=? and state='PENDING' and attempts<1",lease,tenant,id);advanceMonitor(tenant,row.get("incident_id").toString(),"MITIGATING");workflows.audit(tenant,"remediation_claimed",row.get("incident_id").toString(),"demo.recovery_executor",obj("plan_id",id,"execution_key",key,"lease",lease,"correlation_id",id));return lease;}));}
    public Map<String,Object> execute(String tenant,String id,String hash,String key){String lease=claim(tenant,id,hash,key);return executeClaim(tenant,id,hash,lease);}
    public Map<String,Object> executeClaim(String tenant,String id,String hash,String lease){return audited(tenant,id,"execute_claim","demo.recovery_executor",()->{var row=required(tenant,id);integrity(row,hash);if(!"EXECUTING".equals(row.get("state"))||!Objects.equals(lease,row.get("lease")))throw new ApiFailure(409,"Unknown or consumed execution lease");try{executor.execute(tenant,id,lease,payload(row),hash);}catch(Exception failure){db.write(tenant,()->{db.jdbc.update("update remediation_plans set state='REQUIRES_MANUAL_INTERVENTION',outcome='EXECUTOR_FAILED_OR_PARTIAL' where tenant_id=? and id=? and state='EXECUTING' and lease=?",tenant,id,lease);db.jdbc.update("update remediation_outbox set state='MANUAL_INTERVENTION' where tenant_id=? and plan_id=?",tenant,id);workflows.audit(tenant,"remediation_partial_or_failed",row.get("incident_id").toString(),"system.recovery",obj("plan_id",id,"error_type",failure.getClass().getSimpleName(),"correlation_id",id));return null;});return get(tenant,id);}return db.write(tenant,()->{boolean effect=effectMatches(tenant,id,hash);db.jdbc.update("update remediation_plans set state=?,executed_at=now(),outcome=? where tenant_id=? and id=? and state='EXECUTING' and lease=?",effect?"EXECUTED":"REQUIRES_MANUAL_INTERVENTION",effect?"ACKNOWLEDGED_NOT_VERIFIED":"NO_EFFECT_RECEIPT",tenant,id,lease);db.jdbc.update("update remediation_outbox set state=? where tenant_id=? and plan_id=?",effect?"EXECUTED":"MANUAL_INTERVENTION",tenant,id);if(effect)advanceMonitor(tenant,row.get("incident_id").toString(),"VERIFYING");workflows.audit(tenant,"remediation_executor_ack",row.get("incident_id").toString(),"demo.recovery_executor",obj("plan_id",id,"effect_receipt",effect,"resolved",false,"correlation_id",id));return get(tenant,id);});});}
    private boolean effectMatches(String tenant,String id,String hash){return db.jdbc.queryForObject("select count(*) from remediation_effects where tenant_id=? and plan_id=? and plan_hash=?",Integer.class,tenant,id,hash)==1;}
    public Map<String,Object> sample(String tenant,String id){return audited(tenant,id,"sample","demo.recovery_verifier",()->{var row=required(tenant,id);integrity(row,row.get("plan_hash").toString());var result=executor.sample(tenant,payload(row).get("run_id").toString());db.write(tenant,()->{workflows.audit(tenant,"remediation_sampled",row.get("incident_id").toString(),"demo.recovery_verifier",obj("plan_id",id,"sample_id",result.get("sample_id"),"source_mode","SIMULATED","correlation_id",id));return null;});return result;});}
    public Map<String,Object> verify(String tenant,String id,String hash){return audited(tenant,id,"verify","demo.recovery_verifier",()->db.write(tenant,()->{var row=required(tenant,id);integrity(row,hash);if(!row.get("state").equals("EXECUTED"))throw new ApiFailure(409,"Executed effect and independent sample required");var plan=payload(row);var samples=db.jdbc.queryForList("select * from remediation_samples where tenant_id=? and run_id=? and observed_at>=? and observed_at>now()-interval '60 seconds' order by observed_at desc limit 1",tenant,plan.get("run_id"),row.get("executed_at"));var current=db.jdbc.queryForList("select version,disk_percent from replay_resources where tenant_id=? and run_id=?",tenant,plan.get("run_id"));boolean pass=effectMatches(tenant,id,hash)&&!samples.isEmpty()&&!current.isEmpty();if(pass){var sample=samples.getFirst();int version=((Number)plan.get("expected_resource_version")).intValue()+1;double post=((Number)plan.get("post_disk_percent")).doubleValue();pass="SIMULATED".equals(sample.get("source_mode"))&&((Number)sample.get("resource_version")).intValue()==version&&((Number)current.getFirst().get("version")).intValue()==version&&Double.compare(((Number)sample.get("disk_percent")).doubleValue(),post)==0&&Double.compare(((Number)current.getFirst().get("disk_percent")).doubleValue(),post)==0;}
        if(pass){boolean rollback=plan.get("action").equals(ActionRegistry.RESTORE.code());String state=rollback?"ROLLED_BACK":"VERIFIED";db.jdbc.update("update remediation_plans set state=?,verified_at=now(),outcome='INDEPENDENT_SIMULATED_POST_STATE_VERIFIED' where tenant_id=? and id=?",state,tenant,id);if(rollback)db.jdbc.update("update remediation_plans set state='ROLLED_BACK',outcome='NAMED_ROLLBACK_VERIFIED' where tenant_id=? and id=?",tenant,plan.get("parent_plan"));var item=workflows.incident(tenant,row.get("incident_id").toString());item.status=rollback?Lifecycle.closed_unresolved:Lifecycle.resolved;item.timeline.add(obj("at",now(),"kind","verification","event",rollback?"Named ReplayLab rollback verified; fault restored":"Independent simulated post-state verified"));workflows.save(tenant,item);var replayRecord=db.one(Table.REPLAY_RUNS,tenant,plan.get("run_id").toString());var replayPayload=new LinkedHashMap<>(map(replayRecord.get("payload")));replayPayload.put("governed_recovery",obj("plan_id",id,"verification_passed",true,"rollback",rollback,"source_mode","SIMULATED"));db.update(Table.REPLAY_RUNS,tenant,plan.get("run_id").toString(),obj("status",rollback?"rolled_back":"completed","payload",replayPayload));var sample=samples.getFirst();var verified=new ActionRegistry.Verification(id,true,sample.get("observed_at").toString(),((Number)sample.get("resource_version")).intValue(),"SIMULATED","demo.recovery_verifier");db.jdbc.update("insert into remediation_postmortems(tenant_id,plan_id,payload) values(?,?,?::jsonb)",tenant,id,encode(new ActionRegistry.Postmortem(id,item.incident_id,rollback,verified,"PENDING_KNOWLEDGE_REVIEW")));syncMonitor(tenant,item.incident_id,rollback);}
        workflows.audit(tenant,"remediation_verification",row.get("incident_id").toString(),"demo.recovery_verifier",obj("plan_id",id,"passed",pass,"source_mode","SIMULATED","correlation_id",id));return obj("plan_id",id,"passed",pass,"state",get(tenant,id).get("state"),"source_mode","SIMULATED");}));}
    private void advanceMonitor(String tenant,String incident,String state){var rows=db.jdbc.queryForList("select lifecycle from monitor_incidents where tenant_id=? and id=?",String.class,tenant,incident);if(rows.isEmpty()||rows.getFirst().equals(state))return;if(state.equals("AWAITING_APPROVAL")&&!rows.getFirst().equals("INVESTIGATING"))return;if(state.equals("MITIGATING")&&!rows.getFirst().equals("AWAITING_APPROVAL"))return;if(state.equals("VERIFYING")&&!rows.getFirst().equals("MITIGATING"))return;monitoring.transitionForRemediation(tenant,incident,com.investinator.monitoring.MonitoringContracts.Lifecycle.valueOf(state),false);}
    private void syncMonitor(String tenant,String incident,boolean rollback){if(db.jdbc.queryForObject("select count(*) from monitor_incidents where tenant_id=? and id=?",Integer.class,tenant,incident)==0)return;if(!rollback){monitoring.transitionForRemediation(tenant,incident,com.investinator.monitoring.MonitoringContracts.Lifecycle.RESOLVED,true);return;}db.jdbc.update("update monitor_incidents set lifecycle=?,active=false,closed_at=now(),updated_at=now() where tenant_id=? and id=?",rollback?"CLOSED_UNRESOLVED":"RESOLVED",tenant,incident);workflows.audit(tenant,"monitor_governed_verification",incident,"demo.recovery_verifier",obj("rollback",rollback,"independently_verified",true));}
    public Map<String,Object> recover(String tenant,String id){return audited(tenant,id,"recover","demo.recovery_executor",()->db.write(tenant,()->{var row=required(tenant,id);if(!Set.of("EXECUTING","REQUIRES_MANUAL_INTERVENTION").contains(row.get("state"))||row.get("lease_expires_at")==null||((java.sql.Timestamp)row.get("lease_expires_at")).toInstant().isAfter(Instant.now()))throw new ApiFailure(409,"Expired uncertain execution required");integrity(row,row.get("plan_hash").toString());boolean effect=effectMatches(tenant,id,row.get("plan_hash").toString());db.jdbc.update("update remediation_plans set state=?,executed_at=case when ? then now() else executed_at end,outcome=? where tenant_id=? and id=?",effect?"EXECUTED":"REQUIRES_MANUAL_INTERVENTION",effect,effect?"RECOVERED_RECEIPT_REQUIRES_FRESH_SAMPLE":"NO_EFFECT_DO_NOT_AUTORETRY",tenant,id);db.jdbc.update("update remediation_outbox set state=? where tenant_id=? and plan_id=?",effect?"EXECUTED":"MANUAL_INTERVENTION",tenant,id);if(effect)advanceMonitor(tenant,row.get("incident_id").toString(),"VERIFYING");workflows.audit(tenant,"remediation_crash_recovery",row.get("incident_id").toString(),"demo.recovery_executor",obj("plan_id",id,"effect_receipt",effect,"automatic_retry",false,"correlation_id",id));return get(tenant,id);}));}
}
